  },
  loadingRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  loadingText: {
    color: '#38bdf8',
    fontSize: 13,
  },
  readyContainer: {
    flex: 1,
    gap: 8,
  },
  readyText: {
    color: '#38bdf8',
    fontSize: 12,
  },
  telemetryText: {
    color: '#64748b',
    fontSize: 12,
    fontVariant: ['tabular-nums'],
  },
  errorContainer: {
    marginTop: 6,
    gap: 4,
  },
  errorReason: {
    color: '#fda4af',
    fontSize: 12,
  },
  retryButton: {
    marginTop: 6,
    backgroundColor: '#0f172a',
    borderColor: '#475569',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 14,
