import type { NavNode } from '@shared/types'
import { useCallback, useMemo, useState } from 'react'

/* ──────────────── Types ──────────────── */

export interface RouteSelection {
  start: NavNode | null
  destination: NavNode | null
  activeField: 'start' | 'destination'
  bothSelected: boolean
  setStart: (node: NavNode | null) => void
  setDestination: (node: NavNode | null) => void
  setActiveField: (field: 'start' | 'destination') => void
  setFromTap: (node: NavNode) => void
  swap: () => void
  clearStart: () => void
  clearDestination: () => void
  clearAll: () => void
}

/* ──────────────── Hook ──────────────── */

/**
 * Manages route selection state — start (A) and destination (B) nodes.
 *
 * `setFromTap` assigns a tapped node to whichever field `activeField` points to,
 * auto-advancing to the other field afterward. If the tapped node is already the
 * OTHER field, it swaps them instead of duplicating.
 */
export function useRouteSelection(): RouteSelection {
  const [start, setStartState] = useState<NavNode | null>(null)
  const [destination, setDestinationState] = useState<NavNode | null>(null)
  const [activeField, setActiveField] = useState<'start' | 'destination'>('start')

  const setStart = useCallback((node: NavNode | null) => {
    setStartState(node)
    setActiveField('destination')
  }, [])

  const setDestination = useCallback((node: NavNode | null) => {
    setDestinationState(node)
    setActiveField('start')
  }, [])

  const setFromTap = useCallback(
    (node: NavNode) => {
      if (activeField === 'start') {
        // If tapped node is already the destination, swap
        if (destination?.id === node.id) {
          setDestinationState(start)
          setStartState(node)
          setActiveField('destination')
        } else {
          setStartState(node)
          setActiveField('destination')
        }
      } else {
        // activeField === 'destination'
        // If tapped node is already the start, swap
        if (start?.id === node.id) {
          setStartState(destination)
          setDestinationState(node)
          setActiveField('start')
        } else {
          setDestinationState(node)
          setActiveField('start')
        }
      }
    },
    [activeField, start, destination],
  )

  const swap = useCallback(() => {
    if (start === null && destination === null) return
    const prevStart = start
    const prevDest = destination
    setStartState(prevDest)
    setDestinationState(prevStart)
  }, [start, destination])

  const clearStart = useCallback(() => {
    setStartState(null)
    setActiveField('start')
  }, [])

  const clearDestination = useCallback(() => {
    setDestinationState(null)
    setActiveField('destination')
  }, [])

  const clearAll = useCallback(() => {
    setStartState(null)
    setDestinationState(null)
    setActiveField('start')
  }, [])

  const bothSelected = useMemo(() => start !== null && destination !== null, [start, destination])

  return {
    start,
    destination,
    activeField,
    bothSelected,
    setStart,
    setDestination,
    setActiveField,
    setFromTap,
    swap,
    clearStart,
    clearDestination,
    clearAll,
  }
}

/**
 * PathfindingEngine — dual-mode A* with accessibility filtering.
 *
 * Wraps ngraph.path's A* algorithm with the project's type system.
 * Takes a NavGraph, builds an internal ngraph.graph, and exposes
 * findRoute(fromId, toId, mode) for standard and accessible routing.
 *
 * Used by Phase 6 (route visualization) and Phase 7 (turn-by-turn).
 */

import { buildGraph, calculateWeight } from '@shared/pathfinding/graph-builder'
import type { PathResult, PathSegment, RouteMode } from '@shared/pathfinding/types'
import type { NavEdgeData, NavGraph, NavNodeData } from '@shared/types'
import type { Graph, Link, Node } from 'ngraph.graph'
import type { PathFinder } from 'ngraph.path'
import { aStar } from 'ngraph.path'

/** Not-found result constant — reused for all failure responses. */
const NOT_FOUND: PathResult = Object.freeze({
  found: false,
  nodeIds: [],
  totalDistance: 0,
  segments: [],
})

export class PathfindingEngine {
  private readonly graph: Graph<NavNodeData, NavEdgeData>
  private readonly standardFinder: PathFinder<NavNodeData>
  private readonly accessibleFinder: PathFinder<NavNodeData>

  constructor(navGraph: NavGraph) {
    this.graph = buildGraph(navGraph)

    // Standard finder: uses standardWeight, no edge blocking
    this.standardFinder = aStar<NavNodeData, NavEdgeData>(this.graph, {
      distance: (_from: Node<NavNodeData>, _to: Node<NavNodeData>, link: Link<NavEdgeData>) =>
        link.data.standardWeight,
      heuristic: (a: Node<NavNodeData>, b: Node<NavNodeData>) =>
        a.data.floorId !== b.data.floorId
          ? 0
          : calculateWeight(a.data.x, a.data.y, b.data.x, b.data.y),
    })

    // Accessible finder: uses accessibleWeight, blocks non-accessible edges
    this.accessibleFinder = aStar<NavNodeData, NavEdgeData>(this.graph, {
      distance: (_from: Node<NavNodeData>, _to: Node<NavNodeData>, link: Link<NavEdgeData>) =>
        link.data.accessibleWeight,
      heuristic: (a: Node<NavNodeData>, b: Node<NavNodeData>) =>
        a.data.floorId !== b.data.floorId
          ? 0
          : calculateWeight(a.data.x, a.data.y, b.data.x, b.data.y),
      blocked: (_from: Node<NavNodeData>, _to: Node<NavNodeData>, link: Link<NavEdgeData>) =>
        !link.data.accessible,
    })
  }

  /**
   * Find a route between two nodes.
   *
   * @param fromId - Source node ID
   * @param toId - Destination node ID
   * @param mode - 'standard' or 'accessible'
   * @returns PathResult with found status, ordered nodeIds, segments, and totalDistance
   */
  findRoute(fromId: string, toId: string, mode: RouteMode): PathResult {
    // Same start and destination: trivial path
    if (fromId === toId) {
      return { found: true, nodeIds: [fromId], totalDistance: 0, segments: [] }
    }

    // Validate node existence before calling finder (ngraph throws on missing nodes)
    if (!this.graph.hasNode(fromId) || !this.graph.hasNode(toId)) {
      return { ...NOT_FOUND }
    }

    const finder = mode === 'accessible' ? this.accessibleFinder : this.standardFinder

    const rawPath = finder.find(fromId, toId)

    // ngraph.path returns [targetNode] when all paths are blocked — not a valid path
    if (rawPath.length <= 1) {
      return { ...NOT_FOUND }
    }

    // ngraph.path returns destination-first — reverse to get source-first order
    const path = rawPath.reverse()

    const nodeIds: string[] = []
    const segments: PathSegment[] = []
    let totalDistance = 0

    for (let i = 0; i < path.length; i++) {
      const node = path[i]
      if (!node) continue
      const nodeId = node.id as string
      nodeIds.push(nodeId)

      if (i > 0) {
        const prevNode = path[i - 1]
        if (!prevNode) continue
        const prevId = prevNode.id as string
        const link = this.graph.getLink(prevId, nodeId)

        const distance =
          link != null
            ? mode === 'accessible'
              ? link.data.accessibleWeight
              : link.data.standardWeight
            : 0

        segments.push({ fromId: prevId, toId: nodeId, distance })
        totalDistance += distance
      }
    }

    return { found: true, nodeIds, totalDistance, segments }
  }
}

/**
 * Graph construction from NavGraph JSON.
 *
 * Builds a typed ngraph.graph instance from a serialized NavGraph object,
 * handling bidirectional edge expansion and cross-floor edge synthesis.
 * Also exports a Euclidean distance utility used for edge weight calculation
 * and A* heuristic.
 */

import type { NavEdge, NavEdgeData, NavGraph, NavNode, NavNodeData } from '@shared/types'
import type { Graph } from 'ngraph.graph'
import createGraph from 'ngraph.graph'

/**
 * Flattens a multi-floor NavGraph into a single list of nodes and edges.
 *
 * Retained for the admin map editor (MapEditorCanvas.tsx) which depends on
 * this function to flatten the NavGraph before editing and re-wrap it on save.
 * This function is NOT called inside buildGraph as of Phase 17.
 */
export function flattenNavGraph(navGraph: NavGraph): { nodes: NavNode[]; edges: NavEdge[] } {
  const nodes: NavNode[] = []
  const edges: NavEdge[] = []
  for (const building of navGraph.buildings) {
    for (const floor of building.floors) {
      nodes.push(...floor.nodes)
      edges.push(...floor.edges)
    }
  }
  return { nodes, edges }
}

/**
 * Constructs a live ngraph.graph from a serialized NavGraph JSON object.
 *
 * Phase 17 implementation: iterates buildings → floors directly (no longer
 * calls flattenNavGraph internally). After all nodes and intra-floor edges
 * are added, performs a second pass to synthesize bidirectional inter-floor
 * edges from connectsToNodeAboveId on stairs, elevator, and ramp nodes.
 *
 * Inter-floor edge weights:
 * - stairs: standardWeight=0.3, accessibleWeight=Infinity, accessible=false
 * - elevator/ramp: standardWeight=0.3, accessibleWeight=0.45, accessible=true
 *
 * For each node: destructures `{ id, ...data }` and adds to graph.
 * For each intra-floor edge: adds a directed link. If `bidirectional` is true,
 * also adds the reverse directed link so both `graph.getLink(a, b)`
 * and `graph.getLink(b, a)` return a link.
 *
 * The pathfinding engine uses x, y, and weight fields for routing; extra
 * fields (floorId, connector IDs) are stored as node data and passed through.
 */
export function buildGraph(navGraph: NavGraph): Graph<NavNodeData, NavEdgeData> {
  const graph = createGraph<NavNodeData, NavEdgeData>()

  // Pass 1: add all nodes and intra-floor edges from all buildings and floors.
  for (const building of navGraph.buildings) {
    for (const floor of building.floors) {
      for (const { id, ...data } of floor.nodes) {
        graph.addNode(id, data)
      }

      for (const { id: _id, sourceId, targetId, ...data } of floor.edges) {
        // Normalize accessibleWeight to Infinity for non-accessible edges.
        // JSON cannot represent Infinity, so the serialized form uses a large
        // finite number. The graph should carry the true semantic value.
        const edgeData: NavEdgeData = data.accessible
          ? data
          : { ...data, accessibleWeight: Number.POSITIVE_INFINITY }
        graph.addLink(sourceId, targetId, edgeData)
        if (edgeData.bidirectional) {
          graph.addLink(targetId, sourceId, edgeData)
        }
      }
    }
  }

  // Pass 2: synthesize bidirectional inter-floor edges from connector nodes.
  // Only process connectsToNodeAboveId to avoid adding each pair twice
  // (the counterpart node on the floor above has connectsToNodeBelowId pointing
  // back, which would duplicate the edge if we processed both directions here).
  const processedPairs = new Set<string>()

  graph.forEachNode((node) => {
    const data = node.data
    const nodeType = data.type

    if (
      (nodeType === 'stairs' || nodeType === 'elevator' || nodeType === 'ramp') &&
      data.connectsToNodeAboveId != null
    ) {
      const targetId = data.connectsToNodeAboveId
      if (!graph.hasNode(targetId)) return

      // Build a canonical pair key (sorted) to skip duplicates.
      const pairKey = [node.id, targetId].sort().join('|')
      if (processedPairs.has(pairKey)) return
      processedPairs.add(pairKey)

      // Skip if links already exist (e.g. JSON stored inter-floor edges).
      if (graph.hasLink(node.id, targetId) || graph.hasLink(targetId, node.id)) return

      const isAccessible = nodeType === 'elevator' || nodeType === 'ramp'
      const interFloorEdge: NavEdgeData = {
        standardWeight: 0.3,
        accessibleWeight: isAccessible ? 0.45 : Number.POSITIVE_INFINITY,
        accessible: isAccessible,
        bidirectional: true,
      }

      graph.addLink(node.id, targetId, interFloorEdge)
      graph.addLink(targetId, node.id, interFloorEdge)
    }
  })

  return graph
}

/**
 * Computes Euclidean distance between two points.
 *
 * Used by:
 * - Admin editor (Phase 9) to auto-compute edge weights from node coordinates
 * - Pathfinding engine (Plan 02) as the A* heuristic function
 *
 * @param ax - X coordinate of point A
 * @param ay - Y coordinate of point A
 * @param bx - X coordinate of point B
 * @param by - Y coordinate of point B
 * @returns Euclidean distance between the two points
 */
export function calculateWeight(ax: number, ay: number, bx: number, by: number): number {
  return Math.sqrt((ax - bx) ** 2 + (ay - by) ** 2)
}

